/*
 * A191324  Increasing sequence generated by these rules: a(1)=1, and if x is
 *          in a then [3x/2]+1 and 3x+2 are in a, where [ ]=floor.
 * https://oeis.org/A191324
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   not stated
 * Range:     u8 n <= 31, u16 n <= 2517, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   grow_seq_array
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Recurrence: a(1)=1; if x is in a then floor(3x/2)+1 and 3x+2 are in a. */
/* The implementation generates the sequence with a min‑heap and skips
   duplicates.  It works for all provided integer sizes, including the
   arbitrary‑precision build. */
#include <stddef.h>
#include <stdbool.h>
#include <stdlib.h>
#include "../utils/grow_seq_array.h"

/* ---------- heap for candidate values ---------- */
static seq_t *heap_arr = NULL;
static size_t heap_cap = 0;  /* capacity */
static size_t heap_size = 0; /* number of elements */

/* push a value into the min‑heap */
static void heap_push(seq_t val)
{
    /* ensure capacity for one more element */
    grow_seq_array(&heap_arr, &heap_cap, heap_size + 1);

    size_t i = heap_size++;
    while (i > 0) {
        size_t parent = (i - 1) >> 1;
        if (heap_arr[parent] <= val) break;
        heap_arr[i] = heap_arr[parent];
        i = parent;
    }
    heap_arr[i] = val;
}

/* pop the smallest value from the heap */
static seq_t heap_pop(void)
{
    seq_t minv = heap_arr[0];
    seq_t last = heap_arr[--heap_size];
    size_t i = 0;
    while (1) {
        size_t left = (i << 1) + 1;
        if (left >= heap_size) break;
        size_t right = left + 1;
        size_t child = (right < heap_size && heap_arr[right] < heap_arr[left]) ? right : left;
        if (heap_arr[child] >= last) break;
        heap_arr[i] = heap_arr[child];
        i = child;
    }
    heap_arr[i] = last;
    return minv;
}

/* ---------- storage of generated sequence ---------- */
static seq_t *seq_arr = NULL;
static size_t seq_cap = 0;
static size_t seq_len = 0;
static bool initialized = false;

/* ---------- public function ---------- */
seq_t a(idx_t n)
{
    if (n == 0) return (seq_t)0;   /* undefined for 0, but guard */

    if (!initialized) {
        /* initialise heap with the first element */
        heap_push((seq_t)1);
        seq_cap = 0;
        seq_arr = NULL;
        seq_len = 0;
        initialized = true;
    }

    while (seq_len < n) {
        seq_t x = heap_pop();

        /* skip duplicates: output only when new */
        if (seq_len > 0 && x == seq_arr[seq_len - 1])
            continue;

        grow_seq_array(&seq_arr, &seq_cap, seq_len + 1);
        seq_arr[seq_len++] = x;

        /* generate successors */
        seq_t y1 = ((seq_t)3 * x) / 2 + 1;
        seq_t y2 = (seq_t)3 * x + 2;
        heap_push(y1);
        heap_push(y2);
    }

    return seq_arr[n - 1];
}
